--
-- Table structure for table `venues`
--

DROP TABLE IF EXISTS `venues`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `venues` (
  `venue_id` int NOT NULL,
  `venue_name` varchar(255) DEFAULT NULL,
  `city` varchar(100) DEFAULT NULL,
  `country` varchar(100) DEFAULT NULL,
  `capacity` int DEFAULT NULL,
  `timezone` varchar(10) DEFAULT NULL,
  `ends` text,
  `home_team` varchar(100) DEFAULT NULL,
  `image_url` text,
  `total_matches` int DEFAULT NULL,
  `matches_won_batting_first` int DEFAULT NULL,
  `matches_won_bowling_first` int DEFAULT NULL,
  `avg_first_inns` int DEFAULT NULL,
  `avg_second_inns` int DEFAULT NULL,
  `highest_total` varchar(255) DEFAULT NULL,
  `lowest_total` varchar(255) DEFAULT NULL,
  `highest_chased` varchar(255) DEFAULT NULL,
  `lowest_defended` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`venue_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `venues`
